        buffer.writeUInt16LE(channels, 10);
        buffer.writeUInt32LE(sampleRate, 12);
        buffer.writeUInt32LE(byteRate, 16);
        buffer.writeUInt16LE(blockAlign, 20);
        buffer.writeUInt16LE(bitsPerSample, 22);
